import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    results = {}
    for host in network.hosts():
        ip = str(host)
        try:
            response = subprocess.run(['ping', '-c', '1', '-W', '1', ip], capture_output=True, shell=True)
            results[ip] = response.returncode == 0
        except subprocess.CalledProcessError:
            raise
    return results

